/** Queries generated by the core package are accepted by the real OData service (AC-DATA-03, AC-DATA-04). */
import { expect, test } from '@playwright/test';
import {
  buildListRequest, buildObjectRequest, buildValueHelpRequest, loadService, MemoryProvider, ODataV4Provider, type Condition, type FetchLike,
  type MetaModel, type QueryRequest, type Row,
} from '../../packages/core/src';
import { MOCK, open, resetServer, table } from './helpers';

const fetchLike: FetchLike = (url, init) => fetch(url, init);
let model: MetaModel;
let server: ODataV4Provider;
let memory: MemoryProvider;
let suppliers: Row[];

test.beforeAll(async () => {
  ({ model, provider: server } = await loadService({ serviceUrl: `${MOCK}/odata/purchasing/`, fetch: fetchLike, language: 'en' }));
  const all = await server.query({ source: { entitySet: 'Suppliers' }, select: [], expand: [], orderBy: [{ path: 'Supplier', descending: false }], count: false, top: 1000 });
  suppliers = all.rows;
  memory = new MemoryProvider({ model, data: { Suppliers: suppliers } });
});

const keys = (rows: Row[]) => rows.map((r) => r.Supplier);
const supplierRequest = (filters: Record<string, Condition[]>, extra: Partial<QueryRequest> = {}): QueryRequest => ({
  source: { entitySet: 'Suppliers' }, select: ['Supplier', 'SupplierName', 'Country', 'City', 'Rating', 'IsBlocked'], expand: [],
  filters, orderBy: [{ path: 'Supplier', descending: false }], count: true, top: 1000, ...extra,
});

test.describe('AC-DATA-03 server accepts every query class and agrees with the in-memory provider', () => {
  const c = (operator: Condition['operator'], values: unknown[] = [], exclude?: boolean): Condition => ({ operator, values, exclude });
  const cases: [string, Record<string, Condition[]>][] = [
    ['EQ', { Country: [c('EQ', ['DE'])] }],
    ['NE', { Country: [c('NE', ['DE'])] }],
    ['BT', { Supplier: [c('BT', ['0000100010', '0000100030'])] }],
    ['NB', { Supplier: [c('NB', ['0000100010', '0000100190'])] }],
    ['LT/LE/GT/GE decimal', { Rating: [c('GE', ['2.5']), c('LT', ['1.0'])] }],
    ['Contains', { SupplierName: [c('Contains', ['Ltd'])] }],
    ['NotContains', { SupplierName: [c('NotContains', ['a'])] }],
    ['StartsWith/EndsWith', { SupplierName: [c('StartsWith', ['B']), c('EndsWith', ['Inc'])] }],
    ['Empty/NotEmpty', { City: [c('NotEmpty')] }],
    ['include + exclude', { Country: [c('EQ', ['DE']), c('EQ', ['US']), c('EQ', ['US'], true)] }],
    ['boolean', { IsBlocked: [c('EQ', [true])] }],
    ['several fields', { Country: [c('EQ', ['DE'])], Rating: [c('GT', ['3'])] }],
  ];
  for (const [name, filters] of cases) {
    test(`filter ${name}`, async () => {
      const req = supplierRequest(filters);
      const [s, m] = await Promise.all([server.query(req), memory.query(req)]);
      expect(keys(s.rows)).toEqual(keys(m.rows));
      expect(s.count).toBe(m.count);
    });
  }

  test('sorting, paging and count', async () => {
    const req = supplierRequest({}, { orderBy: [{ path: 'Country', descending: true }, { path: 'Supplier', descending: false }], skip: 40, top: 25 });
    const [s, m] = await Promise.all([server.query(req), memory.query(req)]);
    expect(keys(s.rows)).toEqual(keys(m.rows));
    expect(s.count).toBe(suppliers.length);
  });

  test('list requests of the model: first block, next block, search, expand, sort by amount', async () => {
    const ui = model.ui['Purchasing.PurchaseOrder']!;
    for (const o of [
      { skip: 0, top: 100, count: true },
      { skip: 100, top: 100, count: false },
      { skip: 0, top: 100, count: true, search: 'Ltd' },
      { skip: 0, top: 50, count: true, sort: [{ path: 'NetAmount', descending: true }] },
      { skip: 0, top: 50, count: true, filters: { OrderDate: [{ operator: 'BT' as const, values: ['2026-01-01', '2026-06-30'] }], Status: [{ operator: 'EQ' as const, values: ['CLOSED'], exclude: true }] } },
    ]) {
      const res = await server.query(buildListRequest(model, ui, { source: { entitySet: 'PurchaseOrders' }, columns: ui.lineItem, ...o }));
      expect(res.rows.length).toBeGreaterThan(0);
      expect(res.rows[0]!._Supplier).toBeTruthy();
    }
  });

  test('object read, sub-tables and value help', async () => {
    const ui = model.ui['Purchasing.PurchaseOrder']!;
    const row = await server.read("PurchaseOrders('4500000001')", buildObjectRequest(model, 'Purchasing.PurchaseOrder', ui));
    expect(row.PurchaseOrder).toBe('4500000001');
    const items = await server.query(buildListRequest(model, model.ui['Purchasing.PurchaseOrderItem']!, { source: { parent: "PurchaseOrders('4500000001')", navigation: '_Item' }, columns: model.ui['Purchasing.PurchaseOrderItem']!.lineItem, top: 10, skip: 0, count: true }));
    expect(items.count).toBe(150);
    const history = await server.query(buildListRequest(model, model.ui['Purchasing.ItemHistory']!, { source: { parent: "PurchaseOrders('4500000001')/_Item(PurchaseOrder='4500000001',PurchaseOrderItem=10)", navigation: '_History' }, columns: model.ui['Purchasing.ItemHistory']!.lineItem, top: 10, count: true }));
    expect(history.count).toBeUndefined(); // not countable: no $count was sent (the service would answer 400)
    const vl = model.entityTypes['Purchasing.PurchaseOrder']!.properties.Supplier!.valueList!;
    expect((await server.query(buildValueHelpRequest(model, vl))).rows.length).toBe(50);
    expect((await server.query(buildValueHelpRequest(model, vl, { search: 'Ltd' }))).rows.length).toBeGreaterThan(0);
    const plant = model.entityTypes['Purchasing.PurchaseOrderItem']!.properties.Plant!.valueList!;
    expect((await server.query(buildValueHelpRequest(model, plant, { search: 'Ham' }))).rows.length).toBeGreaterThan(0); // contains fallback
  });

  test('AC-DATA-04 decimals and Int64 arrive as exact strings', async () => {
    const res = await server.query({ source: { entitySet: 'PurchaseOrders' }, select: ['PurchaseOrder', 'NetAmount'], expand: [], orderBy: [], count: true, top: 5 });
    for (const r of res.rows) expect(r.NetAmount).toMatch(/^\d+\.\d{2}$/);
  });
});

test('AC-DATA-06 a failing query shows a message strip above the table', async ({ page }) => {
  await resetServer(page);
  await page.route('**/odata/purchasing/PurchaseOrders?*', (route) => route.fulfill({ status: 500, contentType: 'application/json', body: JSON.stringify({ error: { code: 'BOOM', message: 'Database unavailable' } }) }));
  await open(page, '/po');
  await expect(table(page, 'PurchaseOrders').locator('.sk-table__error')).toHaveText('The data could not be loaded: Database unavailable');
});
